"use client";

import { useEffect, useState, useMemo, useCallback, type ReactNode } from "react";
import { Activity, CheckCircle2, ChevronRight, Cpu, KeyRound, Loader2, MessageCircle, Plus, RefreshCw, RotateCcw, ShieldCheck, Wifi, XCircle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { WhatsAppWhitelistWizard } from "@/components/whatsapp/whitelist-wizard";
import { useI18n } from "@/components/i18n-provider";

type EscalationRule = { threshold_hours: number; level: "maker" | "team_lead" | "accounting_manager" | "owner"; priority: "low" | "medium" | "high" | "critical"; recipient_roles?: string[] };
type Policy = { id: string; name: string; description: string | null; client_id: string | null; is_active: boolean; rules?: EscalationRule[] };

function defaultEscalationRule(): EscalationRule { return { threshold_hours: 24, level: "team_lead", priority: "high", recipient_roles: [] }; }
type AiPolicy = Policy & { provider: string; model: string | null; retention_days: number; require_human_confirmation: boolean; allow_sensitive_data: boolean; no_training_required: boolean };
type Connection = { id: string; provider: string; session_id: string | null; status: string; retired_at?: string | null; last_health_check_at: string | null };
type Group = { id: string; connection_id: string; client_id: string | null; provider_group_id: string; group_name: string | null; is_active: boolean };
type Mapping = { id: string; wa_group_id: string; provider_participant_id: string; phone: string | null; display_name: string | null; profile_id: string | null; is_verified: boolean };
type DiscoveredGroup = { id?: string | { _serialized?: string; user?: string; server?: string }; name?: string; subject?: string; groupId?: string | { _serialized?: string; user?: string; server?: string }; groupMetadata?: { id?: { _serialized?: string; user?: string; server?: string }; subject?: string } };
type DiscoveredParticipant = { id?: string | { _serialized?: string; user?: string; server?: string }; lid?: string | { _serialized?: string; user?: string; server?: string }; phone?: string; displayName?: string; name?: string };
type Member = { profile_id: string; name: string; is_active: boolean };
type Role = { id: string; role_key: string; name: string; is_active: boolean };
type Client = { id: string; name: string };
type WhatsAppData = { connections: Connection[]; groups: Group[]; mappings: Mapping[] };
type WaOperationalError = { connectionId: string; status: string; errorCode?: string | null; error?: string | null; createdAt: string };
type WaDeadLetter = { id: string; eventType: string; status: string; retryCount: number; lastRetryAt: string | null; createdAt: string; error?: string | null };
type WaInboxData = { summaries: WaSummary[]; messages: WaMessage[]; operational?: { connections: WaConnectionHealth[]; groups: WaGroupHealth[]; participantMappings: { total: number; verified: number; unverified: number }; lastInboundActivityAt: string | null; ingestion: { messagesInPeriod: number; latestInboundAt: string | null; periodStart: string }; delivery: { attemptsInPeriod: number; byOutcome: Record<string, number>; errors: WaOperationalError[] }; deadLetters: WaDeadLetter[] } };
type WaSummary = { groupId: string; groupName: string; clientId: string | null; messageCount: number; participantCount: number; participants: string[]; latestReceivedAt: string; latestMessage: string; deterministicSummary?: string; aiSummary?: string | null };
type WaMessage = { id: string; groupId: string; groupName: string; senderName: string; content: string; messageType: string; receivedAt: string };
type WaConnectionHealth = { id: string; provider: string; status: string; lastHealthCheckAt: string | null };
type WaGroupHealth = { id: string; groupName: string; clientId: string | null; isActive: boolean; connection: WaConnectionHealth | null };
type WorkItem = { id: string; title: string; client_id: string | null; status?: string; due_at?: string | null };
type AuditSample = { id: string; work_item_id: string; rating: string | null; notes?: string | null; sampled_at: string };
type AuditFinding = { id: string; client_id: string | null; audit_sample_id: string; finding_type: string; severity: string; description?: string | null; evidence?: string | null; root_cause?: string | null; owner_id?: string | null; due_date?: string | null; corrective_task_id?: string | null; status: string; resolution?: string | null; resolved_at?: string | null };
type AuditData = { samples: AuditSample[]; findings: AuditFinding[] };
type EscalationDelivery = { id?: string; status?: string; outcome?: string; sent_at?: string | null; error?: string | null; error_message?: string | null };
type EscalationRecipient = { profile?: { id?: string; full_name?: string; name?: string } | null; notification_id?: string; sent_at?: string | null; deliveries?: EscalationDelivery[] };
type EscalationInstance = { id: string; work_item_id: string; current_level: string; escalated_at: string; resolved_at: string | null; priority: string | null; client: { id: string; name: string } | null; threshold_hours: number | null; recipients: EscalationRecipient[]; notification_delivery_status: EscalationDelivery[]; notes?: string | null; escalation_policies?: { client_id: string | null; name: string }; work_items?: { client_id: string | null; title: string; status: string; due_at: string | null; priority?: string | null } };
type DeadLetter = { id: string; event_type: string; retry_count: number; created_at: string; error_message?: string | null; last_error?: string | null };
type JobHealth = { name: string; status: string; pending: number; processing: number; failed: number; last_activity_at: string | null };
type Capabilities = Record<"integrations" | "escalations" | "escalationManage" | "ai" | "audit" | "auditManage" | "dead" | "deadManage" | "health", boolean>;

export default function AdministrationPage() {
  const { t } = useI18n();
  const tabs = [
    ["whatsapp", t("admin.whatsapp"), MessageCircle],
    ["escalation", t("admin.escalation"), ShieldCheck],
    ["ai", t("admin.aiPolicy"), Cpu],
    ["audit", t("admin.audit"), CheckCircle2],
    ["dead", t("admin.deadQueue"), RotateCcw],
    ["health", t("admin.health"), Activity],
  ] as const;
  const [tab, setTab] = useState("whatsapp");
  const [capabilities, setCapabilities] = useState<Capabilities>({ integrations: false, escalations: false, escalationManage: false, ai: false, audit: false, auditManage: false, dead: false, deadManage: false, health: false });
  const [wa, setWa] = useState<WhatsAppData>({ connections: [], groups: [], mappings: [] });
  const [members, setMembers] = useState<Member[]>([]);
  const [roles, setRoles] = useState<Role[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [policies, setPolicies] = useState<Policy[]>([]);
  const [aiPolicies, setAiPolicies] = useState<AiPolicy[]>([]);
  const [audits, setAudits] = useState<AuditData>({ samples: [], findings: [] });
  const [escalations, setEscalations] = useState<EscalationInstance[]>([]);
  const [waInbox, setWaInbox] = useState<WaInboxData>({ summaries: [], messages: [] });
  const [workItems, setWorkItems] = useState<WorkItem[]>([]);
  const [deadLetters, setDeadLetters] = useState<DeadLetter[]>([]);
  const [deadLetterTotal, setDeadLetterTotal] = useState(0);
  const [jobHealth, setJobHealth] = useState<JobHealth[]>([]);
  const [policyName, setPolicyName] = useState("");
  const [editingPolicy, setEditingPolicy] = useState<Policy | null>(null);
  const [session, setSession] = useState("");
  const [selectedConnection, setSelectedConnection] = useState<string | null>(null);
  const [selectedClientId, setSelectedClientId] = useState<string | null>(null);
  const [qrUrl, setQrUrl] = useState<string | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState<{ type: "success" | "error"; text: string } | null>(null);
  const [partialFailures, setPartialFailures] = useState<string[]>([]);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [retirementTarget, setRetirementTarget] = useState<Connection | null>(null);
  const [groupId, setGroupId] = useState("");
  const [providerGroupId, setProviderGroupId] = useState("");
  const [groupName, setGroupName] = useState("");
  const [participantId, setParticipantId] = useState("");
  const [participantName, setParticipantName] = useState("");
  const [participantProfile, setParticipantProfile] = useState("");
  const [editingMappingId, setEditingMappingId] = useState<string | null>(null);
  const [discoveredGroups, setDiscoveredGroups] = useState<DiscoveredGroup[]>([]);
  const [discoveredParticipants, setDiscoveredParticipants] = useState<DiscoveredParticipant[]>([]);

  async function load(silent = false) {
    if (!silent) setLoading(true);
    setMessage(null);
    setLoadError(null);
    try {
      const capabilityResponse = await fetch("/api/auth/capabilities", { cache: "no-store" });
      const capabilityBody = capabilityResponse.ok ? await capabilityResponse.json() : null;
      if (!capabilityResponse.ok || !capabilityBody?.administration) throw new Error("Hak akses administrasi belum dapat dimuat.");
      const nextCapabilities: Capabilities = { ...capabilities, ...capabilityBody.administration };
      setCapabilities(nextCapabilities);
      const requests = [
        nextCapabilities.integrations ? fetch("/api/admin/whatsapp") : Promise.resolve(null),
        nextCapabilities.escalations ? fetch("/api/admin/escalations") : Promise.resolve(null),
        nextCapabilities.audit ? fetch("/api/admin/audits") : Promise.resolve(null),
        fetch("/api/wa-inbox"),
        fetch("/api/work-items?limit=100"),
        nextCapabilities.dead ? fetch("/api/admin/dead-letters") : Promise.resolve(null),
        nextCapabilities.health ? fetch("/api/admin/job-health") : Promise.resolve(null),
        nextCapabilities.ai ? fetch("/api/admin/ai-policies") : Promise.resolve(null),
        fetch("/api/settings/members"),
        fetch("/api/settings/roles"),
        fetch("/api/clients"),
      ];
      const responses = await Promise.allSettled(requests);
      const names = ["WhatsApp", "eskalasi", "audit", "WhatsApp inbox", "work items", "antrean gagal", "kesehatan pekerjaan", "kebijakan AI", "anggota", "client"];
      setPartialFailures(responses.flatMap((result, index) => result.status === "rejected" || (result.value && !result.value.ok) ? [names[index]] : []));
      const body = await Promise.all(responses.map(async (result) => result.status === "fulfilled" && result.value?.ok ? result.value.json() : null));
      if (body[0]) setWa({ connections: body[0].connections ?? [], groups: body[0].groups ?? [], mappings: body[0].mappings ?? [] });
      if (body[1]) { setPolicies(body[1].policies ?? body[1]); setEscalations(body[1].instances ?? []); }
      if (body[2]) setAudits({ samples: body[2].samples ?? [], findings: body[2].findings ?? [] });
      if (body[3]) setWaInbox({ summaries: body[3].summaries ?? [], messages: body[3].messages ?? [], operational: body[3].operational });
      if (body[4]) setWorkItems((body[4].data ?? body[4].work_items ?? body[4] ?? []) as WorkItem[]);
      if (body[5]) {
        const deadLetterBody = Array.isArray(body[5]) ? { items: body[5], total: body[5].length } : body[5];
        setDeadLetters((deadLetterBody.items ?? []) as DeadLetter[]);
        setDeadLetterTotal(deadLetterBody.total ?? deadLetterBody.items?.length ?? 0);
      }
      if (body[6]) setJobHealth(body[6].workers ?? []);
      if (body[7]) setAiPolicies(body[7]);
      if (body[8]) setMembers((body[8] as Member[]).filter((item) => item.is_active));
      if (body[9]) setRoles(((body[9].roles ?? []) as Role[]).filter((item) => item.is_active));
      if (body[10]) setClients((body[10].data ?? []).map((item: Client) => ({ id: item.id, name: item.name })));
    } catch (error) {
      setLoadError(error instanceof Error ? error.message : "Data administrasi belum dapat dimuat.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => { const timer = window.setTimeout(() => void load(), 0); return () => window.clearTimeout(timer); }, []);
  useEffect(() => () => { if (qrUrl) URL.revokeObjectURL(qrUrl); }, [qrUrl]);

  function notify(type: "success" | "error", text: string) { setMessage({ type, text }); window.setTimeout(() => setMessage(null), 4500); }

  async function action(key: string, request: () => Promise<Response>, success: string, reload = true) {
    setBusy(key); setMessage(null);
    try { const response = await request(); const body = await response.json().catch(() => null); if (!response.ok) throw new Error(body?.error ?? "Aksi gagal diproses."); notify("success", body?.message ?? success); if (reload) await load(true); return body; } catch (error) { notify("error", error instanceof Error ? error.message : "Aksi gagal diproses."); return null; } finally { setBusy(null); }
  }

  async function createConnection() {
    if (!session.trim()) return notify("error", "ID sesi WAHA wajib diisi.");
    await action("create", () => fetch("/api/admin/whatsapp", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "connection", session_id: session.trim(), status: "starting" }) }), "Session WAHA berhasil dibuat dan dimulai.");
    setSession("");
  }

  async function showQr(connection: Connection) {
    if (connection.status === "retired") return notify("error", "Connection sudah retired dan tidak dapat digunakan.");
    setBusy(`qr-${connection.id}`); setSelectedConnection(connection.id); setQrUrl(null);
    try { const response = await fetch(`/api/admin/whatsapp?action=qr&id=${connection.id}`); if (!response.ok) { const body = await response.json().catch(() => null); throw new Error([body?.error, body?.action].filter(Boolean).join(" ") || "QR belum tersedia."); } setQrUrl(URL.createObjectURL(await response.blob())); } catch (error) { notify("error", error instanceof Error ? error.message : "QR belum tersedia."); } finally { setBusy(null); }
  }

  async function retireConnection() {
    if (!retirementTarget) return;
    const target = retirementTarget;
    setRetirementTarget(null);
    await action(`retire-${target.id}`, () => fetch("/api/admin/whatsapp", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "retire", id: target.id }) }), "Session WhatsApp berhasil dihapus.");
    if (selectedConnection === target.id) {
      setSelectedConnection(null);
      setQrUrl(null);
    }
  }

  async function createGroup() {
    if (!selectedConnection || !providerGroupId.trim()) return notify("error", "Pilih koneksi dan isi ID grup WhatsApp.");
    await action("group", () => fetch("/api/admin/whatsapp", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "group", connection_id: selectedConnection, client_id: selectedClientId, provider_group_id: providerGroupId.trim(), group_name: groupName.trim() || null, is_verified: true }) }), "Grup berhasil ditambahkan ke whitelist.");
    setProviderGroupId(""); setGroupName("");
  }

  async function createMapping() {
    if (!groupId || !participantId.trim() || !participantProfile) return notify("error", "Pilih grup, isi participant ID, dan pilih anggota.");
    const participant = discoveredParticipants.find((item) => {
      const id = typeof item.id === "string" ? item.id : item.id?._serialized;
      const lid = typeof item.lid === "string" ? item.lid : item.lid?._serialized;
      return id === participantId || lid === participantId || item.phone === participantId;
    });
    const mappingPayload = { action: "mapping", ...(editingMappingId ? { id: editingMappingId } : {}), wa_group_id: groupId, provider_participant_id: participantId.trim(), phone: participant?.phone ?? null, display_name: participantName.trim() || participant?.displayName || participant?.name || null, profile_id: participantProfile, is_verified: true };
    const body = await action("mapping", () => fetch("/api/admin/whatsapp", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(mappingPayload) }), "Kontak berhasil diverifikasi.", false);
    if (body) {
      setWa((current) => ({ ...current, mappings: [...current.mappings.filter((item) => item.id !== body.id), body] }));
      setParticipantId(""); setParticipantName(""); setParticipantProfile(""); setEditingMappingId(null);
    }
  }

  async function activateGroup(group: Group) {
    await action(`activate-group-${group.id}`, () => fetch("/api/admin/whatsapp", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "activate-group", id: group.id }) }), "Grup WhatsApp berhasil diaktifkan kembali.");
  }

  async function deactivateGroup(group: Group) {
    if (!window.confirm(`Nonaktifkan grup ${group.group_name || group.provider_group_id}?`)) return;
    await action(`deactivate-group-${group.id}`, () => fetch("/api/admin/whatsapp", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "deactivate-group", id: group.id }) }), "Grup WhatsApp berhasil dinonaktifkan.");
  }

  function closeQr() {
    setQrUrl(null);
  }

  async function archiveConnection(connection: Connection) {
    if (!window.confirm(`Hapus ${connection.session_id || "session ini"} dari daftar? History pesan dan audit tetap disimpan.`)) return;
    await action(`archive-${connection.id}`, () => fetch("/api/admin/whatsapp", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "archive-retired", id: connection.id }) }), "Session dihapus dari daftar. History tetap tersimpan.");
  }

  async function unverifyMapping(mapping: Mapping) {
    if (!window.confirm(`Batalkan verifikasi ${mapping.display_name || mapping.provider_participant_id}?`)) return;
    await action(`unverify-mapping-${mapping.id}`, () => fetch("/api/admin/whatsapp", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "unverify-mapping", id: mapping.id }) }), "Verifikasi kontak berhasil dibatalkan.");
  }

  async function verifyMapping(mapping: Mapping) {
    setGroupId(mapping.wa_group_id);
    setParticipantId(mapping.provider_participant_id);
    setParticipantName(mapping.display_name ?? "");
    setParticipantProfile(mapping.profile_id ?? "");
    setEditingMappingId(mapping.id);
    const group = wa.groups.find((item) => item.id === mapping.wa_group_id);
    setDiscoveredParticipants([]);
    if (group?.provider_group_id) await discoverParticipants(group.provider_group_id);
    notify("success", "Kontak lama sudah diisi. Ubah jika diperlukan, lalu klik Verifikasi kontak.");
  }

  async function discoverGroups() {
    if (!selectedConnection) return notify("error", "Pilih koneksi WAHA terlebih dahulu.");
    const selected = wa.connections.find((item) => item.id === selectedConnection);
    if (selected && !["working", "connected", "healthy"].includes(selected.status.toLowerCase())) return notify("error", "Session belum siap. Scan QR dan tunggu status WORKING sebelum memuat grup.");
    setBusy("discover-groups");
    try {
      const response = await fetch(`/api/admin/whatsapp?action=discover-groups&id=${selectedConnection}`, { cache: "no-store" });
      const body = await response.json().catch(() => null);
      if (!response.ok) throw new Error(body?.error ?? "Discovery grup gagal.");
      setDiscoveredGroups(body.groups ?? []);
      setDiscoveredParticipants([]);
      notify("success", "Daftar grup dari WAHA berhasil dimuat.");
    } catch (error) { notify("error", error instanceof Error ? error.message : "Discovery grup gagal."); } finally { setBusy(null); }
  }

  async function discoverParticipants(providerId: string) {
    if (!selectedConnection || !providerId) return;
    setBusy("discover-participants");
    try {
      const response = await fetch(`/api/admin/whatsapp?action=discover-participants&id=${selectedConnection}&group_id=${encodeURIComponent(providerId)}`, { cache: "no-store" });
      const body = await response.json().catch(() => null);
      if (!response.ok) throw new Error(body?.error ?? "Discovery peserta gagal.");
      setDiscoveredParticipants(body.participants ?? []);
    } catch (error) { notify("error", error instanceof Error ? error.message : "Discovery peserta gagal."); } finally { setBusy(null); }
  }

  async function savePolicy(kind: "escalation" | "ai", policy: Policy | AiPolicy | null = null) {
    const value = (policy as Policy | AiPolicy | null)?.name ?? policyName;
    if (!value.trim()) return notify("error", "Nama kebijakan wajib diisi.");
    const payload = { ...(policy as Policy | AiPolicy | null), name: value.trim() };
    await action(`policy-${kind}`, () => fetch(kind === "ai" ? "/api/admin/ai-policies" : "/api/admin/escalations", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }), "Kebijakan berhasil disimpan.");
    if (kind === "escalation") setPolicyName("");
    setEditingPolicy(null);
  }

  async function deleteEscalationPolicy(policy: Policy) {
    if (!window.confirm(`Hapus kebijakan “${policy.name}”? Jika sudah memiliki histori eskalasi, kebijakan akan dinonaktifkan agar histori tetap aman.`)) return;
    const result = await action(`delete-policy-${policy.id}`, () => fetch("/api/admin/escalations", { method: "DELETE", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id: policy.id }) }), "Kebijakan berhasil dihapus atau dinonaktifkan.");
    if (result) {
      setPolicies((current) => current.filter((item) => item.id !== policy.id));
      if (editingPolicy?.id === policy.id) setEditingPolicy(null);
    }
  }

  if (loading) return <main className="page-canvas"><div className="mx-auto max-w-6xl space-y-5"><Skeleton /><Skeleton /><Skeleton /></div></main>;
  if (loadError) return <main className="page-canvas"><div className="mx-auto max-w-2xl rounded-2xl border border-red-200 bg-red-50 p-6 text-red-900"><h1 className="text-lg font-bold">Administrasi belum siap</h1><p className="mt-2 text-sm">{loadError}</p><Button className="mt-4" variant="outline" onClick={() => void load()}><RefreshCw className="size-4" />Coba lagi</Button></div></main>;

  return <main className="page-canvas text-slate-900"><div className="mx-auto w-full max-w-6xl space-y-6">
    <header><div className="flex flex-wrap items-center gap-2 text-xs font-medium text-blue-600"><KeyRound className="size-4" /> Control Center <ChevronRight className="size-3 text-slate-400" /> Administrasi</div><div className="mt-3 flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><h1 className="text-2xl font-bold tracking-tight text-slate-950 sm:text-3xl">Administrasi operasional</h1><p className="mt-1 max-w-2xl text-sm leading-6 text-slate-500">Kelola integrasi, kebijakan kontrol, audit, antrean gagal, dan kesehatan sistem dari satu tempat.</p></div><Button variant="outline" onClick={() => void load()} disabled={loading}><RefreshCw className={`size-4 ${loading ? "animate-spin" : ""}`} /> Segarkan data</Button></div></header>
    <div className="grid gap-3 sm:grid-cols-3"><Summary icon={Wifi} label="Koneksi WhatsApp" value={`${wa.connections.filter((item) => item.status !== "retired").length}`} hint="aktif atau tersedia" /><Summary icon={ShieldCheck} label="Kebijakan aktif" value={`${policies.filter((item) => item.is_active).length + aiPolicies.filter((item) => item.is_active).length}`} hint="eskalasi dan AI" /><Summary icon={Activity} label="Worker bermasalah" value={`${jobHealth.filter((item) => item.status === "degraded").length}`} hint="perlu perhatian" /></div>
    {partialFailures.length > 0 && <div role="alert" className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-900"><span>Data belum tersedia: {partialFailures.join(", ")}.</span><Button size="sm" variant="outline" onClick={() => void load()} className="border-amber-300 bg-white">Coba lagi</Button></div>}
    {message && <div role="status" className={`rounded-xl border px-4 py-3 text-sm ${message.type === "success" ? "border-emerald-200 bg-emerald-50 text-emerald-800" : "border-red-200 bg-red-50 text-red-800"}`}>{message.text}</div>}
    <div role="tablist" aria-label="Bagian administrasi" className="flex max-w-full gap-2 overflow-x-auto border-b border-slate-200 pb-2">{tabs.filter(([value]) => capabilities[value === "whatsapp" ? "integrations" : value === "escalation" ? "escalations" : value]).map(([value, label, Icon]) => <button key={value} id={`tab-${value}`} role="tab" aria-selected={tab === value} aria-controls={`panel-${value}`} onClick={() => setTab(value)} className={`flex shrink-0 items-center gap-2 rounded-lg px-3 py-2 text-sm font-semibold transition-colors ${tab === value ? "bg-blue-600 text-white shadow-sm" : "text-slate-600 hover:bg-slate-100"}`}><Icon className="size-4" />{label}{((value === "escalation" && !capabilities.escalationManage) || (value === "audit" && !capabilities.auditManage) || (value === "dead" && !capabilities.deadManage)) && <span className="text-[11px] font-normal opacity-75">Read-only</span>}</button>)}</div>
    <div id={`panel-${tab}`} role="tabpanel" aria-labelledby={`tab-${tab}`}>{tab === "whatsapp" && capabilities.integrations && <><WhatsAppWhitelistWizard data={wa} members={members} clients={clients} session={session} setSession={setSession} selected={selectedConnection} selectedClientId={selectedClientId} onClientChange={setSelectedClientId} qrUrl={qrUrl} busy={busy} groupId={groupId} setGroupId={setGroupId} providerGroupId={providerGroupId} setProviderGroupId={setProviderGroupId} groupName={groupName} setGroupName={setGroupName} participantId={participantId} setParticipantId={setParticipantId} participantName={participantName} setParticipantName={setParticipantName} participantProfile={participantProfile} setParticipantProfile={setParticipantProfile} discoveredGroups={discoveredGroups} discoveredParticipants={discoveredParticipants} onDiscoverGroups={discoverGroups} onDiscoverParticipants={discoverParticipants} onCreate={createConnection} onSelect={(id) => { setSelectedConnection(id); setDiscoveredGroups([]); setDiscoveredParticipants([]); }} onQr={showQr} onQrClose={closeQr} onHealth={(id) => action(`health-${id}`, () => fetch(`/api/admin/whatsapp?action=status&id=${id}`), "Status koneksi diperbarui.")} onStart={(id) => action(`start-${id}`, () => fetch("/api/admin/whatsapp", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "start", id }) }), "Session WAHA dimulai. Silakan cek status koneksi.")} onStop={(id) => action(`stop-${id}`, () => fetch("/api/admin/whatsapp", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "stop", id }) }), "Koneksi WhatsApp berhasil diputuskan.")} onRetire={setRetirementTarget} onArchive={archiveConnection} onAddGroup={createGroup} onAddMapping={createMapping} onDeactivateGroup={deactivateGroup} onActivateGroup={activateGroup} onUnverifyMapping={unverifyMapping} onVerifyMapping={verifyMapping} onDone={() => notify("success", "Konfigurasi WhatsApp selesai dan siap digunakan.")} /><WhatsAppOperationalPanel data={waInbox} groups={wa.groups} connections={wa.connections} /></>}{tab === "escalation" && capabilities.escalations && <div className="space-y-5"><EscalationOperationsPanel items={escalations} clients={clients} canManage={capabilities.escalationManage} busy={busy} onResolve={(id) => action(`resolve-escalation-${id}`, () => fetch("/api/admin/escalations", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "resolve", id }) }), "Eskalasi diselesaikan.")} /><EscalationPolicyPanel value={policyName} setValue={setPolicyName} policies={policies} busy={busy === "policy-escalation"} clients={clients} roles={roles} canManage={capabilities.escalationManage} editing={editingPolicy} onEdit={setEditingPolicy} onSave={(policy) => void savePolicy("escalation", policy)} onDelete={deleteEscalationPolicy} /></div>}{tab === "ai" && capabilities.ai && <AiPolicyPanel policies={aiPolicies} busy={busy === "policy-ai"} clients={clients} onSave={(policy) => void savePolicy("ai", policy)} />}{tab === "audit" && capabilities.audit && <AuditPanel audits={audits} busy={busy} canManage={capabilities.auditManage} workItems={workItems} members={members} clients={clients} onSample={(payload) => void action("sample", () => fetch("/api/admin/audits", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }), "Sampel audit berhasil dibuat.")} onFinding={(payload) => void action("finding", () => fetch("/api/admin/audits", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }), "Finding berhasil dibuat.")} onStatus={(id, status, resolution) => void action(`finding-${id}`, () => fetch("/api/admin/audits", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "update_finding", id, status, resolution }) }), "Status finding diperbarui.")} />}{tab === "dead" && capabilities.dead && <DeadPanel items={deadLetters} total={deadLetterTotal} busy={busy} canManage={capabilities.deadManage} onRetry={(id) => action(`retry-${id}`, () => fetch("/api/admin/dead-letters", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id }) }), "Event dimasukkan kembali ke antrean. Hasil akan terlihat setelah worker memprosesnya.")} />}{tab === "health" && capabilities.health && <HealthPanel items={jobHealth} />}</div>
       <Dialog open={retirementTarget !== null} onOpenChange={(open) => { if (!open) setRetirementTarget(null); }}><DialogContent><DialogHeader><DialogTitle>Hapus session WhatsApp?</DialogTitle><DialogDescription>Session {retirementTarget?.session_id || "ini"} akan dihapus dari WAHA dan tidak dapat diaktifkan kembali dari aplikasi. Semua grup whitelist terkait ikut dinonaktifkan.</DialogDescription></DialogHeader><DialogFooter><Button variant="outline" onClick={() => setRetirementTarget(null)}>Batal</Button><Button variant="destructive" onClick={() => void retireConnection()} disabled={busy === `retire-${retirementTarget?.id}`}><XCircle className="size-4" />{busy === `retire-${retirementTarget?.id}` ? "Menghapus..." : "Hapus session"}</Button></DialogFooter></DialogContent></Dialog>
  </div></main>;
}

function Summary({ icon: Icon, label, value, hint }: { icon: typeof Activity; label: string; value: string; hint: string }) { return <div className="surface-card rounded-xl p-4"><div className="flex items-center gap-2 text-xs font-semibold text-slate-500"><Icon className="size-4 text-blue-600" />{label}</div><div className="mt-2 text-2xl font-bold text-slate-950">{value}</div><p className="text-xs text-slate-500">{hint}</p></div>; }
function Skeleton() { return <div className="h-28 animate-pulse rounded-xl bg-white shadow-sm" />; }
function Panel({ title, description, children, action }: { title: string; description: string; children: ReactNode; action?: ReactNode }) { return <section className="surface-card rounded-2xl p-5 sm:p-6"><div className="mb-5 flex flex-wrap items-start justify-between gap-3"><div><h2 className="text-lg font-bold text-slate-950">{title}</h2><p className="mt-1 text-sm text-slate-500">{description}</p></div>{action}</div>{children}</section>; }
function Status({ value }: { value: string }) { const healthy = ["connected", "working", "healthy"].includes(value.toLowerCase()); return <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-semibold ${healthy ? "bg-emerald-50 text-emerald-700" : "bg-amber-50 text-amber-700"}`}><span className={`size-1.5 rounded-full ${healthy ? "bg-emerald-500" : "bg-amber-500"}`} />{value}</span>; }
function clientOptions(clients: Client[]) { return <><option value="">Semua client dalam organisasi</option>{clients.map((client) => <option key={client.id} value={client.id}>{client.name}</option>)}</>; }
function EscalationPolicyPanel({ value, setValue, policies, busy, clients, roles, canManage, editing, onEdit, onSave, onDelete }: { value: string; setValue: (value: string) => void; policies: Policy[]; busy: boolean; clients: Client[]; roles: Role[]; canManage: boolean; editing: Policy | null; onEdit: (policy: Policy | null) => void; onSave: (policy: Policy) => void; onDelete: (policy: Policy) => void }) {
  const emptyDraft: Policy = { id: "", name: "", description: null, client_id: null, is_active: true, rules: [defaultEscalationRule()] };
  const [dialogOpen, setDialogOpen] = useState(false);
  const [draft, setDraft] = useState<Policy>(emptyDraft);
  const openCreate = () => { setDraft({ ...emptyDraft, name: value }); setDialogOpen(true); };
  const openEdit = (policy: Policy) => { onEdit(policy); setDraft({ ...policy, rules: policy.rules?.length ? policy.rules : [defaultEscalationRule()] }); setDialogOpen(true); };
  const closeDialog = () => { setDialogOpen(false); setDraft({ ...emptyDraft }); onEdit(null); setValue(""); };
  const update = (next: Partial<Policy>) => setDraft((current) => ({ ...current, ...next }));
  const rules = draft.rules ?? [];
  const save = () => { onSave(draft); closeDialog(); };
  return <Panel title="Kebijakan eskalasi" description="Tentukan kapan pekerjaan melewati deadline harus dieskalasi, kepada siapa, dan dengan prioritas apa." action={<ShieldCheck className="size-5 text-blue-600" />}>
    <div className="flex justify-end"><Button className="cta-primary" disabled={!canManage} onClick={openCreate}><Plus className="size-4" />Buat kebijakan</Button></div>
    <div className="mt-4 divide-y divide-slate-100">{policies.length ? policies.map((item) => { const hasRules = Boolean(item.rules?.length); return <div key={item.id} className="flex flex-wrap items-center justify-between gap-3 py-3"><div><p className="font-semibold">{item.name}</p><p className="text-xs text-slate-500">{item.client_id ? clients.find((client) => client.id === item.client_id)?.name ?? "Client" : "Semua client dalam organisasi"} · {item.rules?.length ?? 0} aturan</p></div><div className="flex flex-wrap items-center gap-2"><Status value={item.is_active ? (hasRules ? "active" : "Belum dikonfigurasi") : "inactive"} />{canManage && <><Button size="sm" variant="outline" onClick={() => openEdit(item)}>Edit</Button><Button size="sm" variant="outline" disabled={busy} onClick={() => onSave({ ...item, is_active: !item.is_active })}>{item.is_active ? "Nonaktifkan" : "Aktifkan"}</Button><Button size="sm" variant="destructive" disabled={busy} onClick={() => onDelete(item)}>Hapus</Button></>}</div></div>; }) : <Empty icon={ShieldCheck} text="Belum ada kebijakan eskalasi." />}</div>
    <Dialog open={dialogOpen} onOpenChange={(open) => { if (!open) closeDialog(); }}><DialogContent className="max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>{draft.id ? "Edit kebijakan eskalasi" : "Buat kebijakan eskalasi"}</DialogTitle><DialogDescription>Atur cakupan client dan seluruh tingkat eskalasi dalam satu kebijakan.</DialogDescription></DialogHeader><div className="grid gap-4 py-2"><label className="text-sm font-semibold text-slate-700">Nama kebijakan<Input className="mt-1.5" aria-label="Nama kebijakan eskalasi" placeholder="Nama kebijakan" value={draft.name} onChange={(event) => update({ name: event.target.value })} /></label><label className="text-sm font-semibold text-slate-700">Berlaku untuk client<select aria-label="Berlaku untuk client" className="mt-1.5 h-9 w-full rounded-lg border border-input bg-white px-2 text-sm font-normal" value={draft.client_id ?? ""} onChange={(event) => update({ client_id: event.target.value || null })}>{clientOptions(clients)}</select></label><div><p className="text-sm font-bold text-slate-950">Aturan eskalasi</p><p className="mt-1 text-xs text-slate-500">Atur threshold, jenjang, prioritas, dan role penerima notifikasi.</p><div className="mt-3 space-y-3">{rules.map((rule, index) => <div key={index} className="grid gap-2 rounded-xl border border-slate-200 p-3 sm:grid-cols-5"><label className="text-xs font-semibold text-slate-600">Threshold (jam)<Input aria-label={`Threshold jam setelah deadline aturan ${index + 1}`} type="number" min="1" value={rule.threshold_hours} onChange={(event) => update({ rules: rules.map((item, itemIndex) => itemIndex === index ? { ...item, threshold_hours: Number(event.target.value) } : item) })} /></label><label className="text-xs font-semibold text-slate-600">Level<select aria-label={`Level eskalasi aturan ${index + 1}`} className="mt-1 h-9 w-full rounded-lg border border-input bg-white px-2 text-sm" value={rule.level} onChange={(event) => update({ rules: rules.map((item, itemIndex) => itemIndex === index ? { ...item, level: event.target.value as EscalationRule["level"] } : item) })}><option value="maker">Maker</option><option value="team_lead">Team lead</option><option value="accounting_manager">Accounting manager</option><option value="owner">Owner</option></select></label><label className="text-xs font-semibold text-slate-600">Prioritas<select aria-label={`Prioritas pekerjaan aturan ${index + 1}`} className="mt-1 h-9 w-full rounded-lg border border-input bg-white px-2 text-sm" value={rule.priority} onChange={(event) => update({ rules: rules.map((item, itemIndex) => itemIndex === index ? { ...item, priority: event.target.value as EscalationRule["priority"] } : item) })}><option value="low">Rendah</option><option value="medium">Sedang</option><option value="high">Tinggi</option><option value="critical">Kritis</option></select></label><label className="text-xs font-semibold text-slate-600">Role penerima<select multiple aria-label={`Role penerima notifikasi aturan ${index + 1}`} className="mt-1 min-h-20 w-full rounded-lg border border-input bg-white px-2 py-1 text-sm" value={rule.recipient_roles ?? []} onChange={(event) => update({ rules: rules.map((item, itemIndex) => itemIndex === index ? { ...item, recipient_roles: Array.from(event.target.selectedOptions, (option) => option.value) } : item) })}>{roles.length ? roles.map((role) => <option key={role.id} value={role.role_key}>{role.name}</option>) : <option disabled>Role aktif belum tersedia</option>}</select></label><Button variant="outline" onClick={() => update({ rules: rules.filter((_, itemIndex) => itemIndex !== index) })} disabled={rules.length === 1}>Hapus</Button></div>)}</div><Button className="mt-3" variant="outline" onClick={() => update({ rules: [...rules, { threshold_hours: (rules.at(-1)?.threshold_hours ?? 0) + 24, level: "owner", priority: "critical", recipient_roles: [] }] })}>Tambah tingkat eskalasi</Button></div></div><DialogFooter><Button variant="outline" onClick={closeDialog}>Batal</Button><Button className="cta-primary" disabled={busy} onClick={save}>{busy ? <Loader2 className="size-4 animate-spin" /> : <Plus className="size-4" />}{draft.id ? "Simpan perubahan" : "Buat kebijakan"}</Button></DialogFooter></DialogContent></Dialog>
  </Panel>;
}
function AiPolicyPanel({ policies, busy, clients, onSave }: { policies: AiPolicy[]; busy: boolean; clients: Client[]; onSave: (policy: AiPolicy) => void }) {
  const emptyDraft: AiPolicy = { id: "", name: "", description: null, client_id: null, is_active: true, provider: "openrouter", model: "", retention_days: 90, require_human_confirmation: true, allow_sensitive_data: false, no_training_required: true };
  const [dialogOpen, setDialogOpen] = useState(false);
  const [draft, setDraft] = useState<AiPolicy>(emptyDraft);
  const fields = [["require_human_confirmation", "Perlu persetujuan manusia", "AI hanya memberi saran. User tetap mengambil keputusan."], ["allow_sensitive_data", "Boleh memproses data sensitif", "Izinkan data keuangan atau data client dikirim ke AI."], ["no_training_required", "Data tidak untuk melatih AI", "Provider tidak boleh memakai data organisasi untuk training."]] as const;
  function openCreate() { setDraft({ ...emptyDraft }); setDialogOpen(true); }
  function openEdit(item: AiPolicy) { setDraft({ ...item }); setDialogOpen(true); }
  function closeDialog() { setDialogOpen(false); setDraft({ ...emptyDraft }); }
  function submit() { onSave(draft); closeDialog(); }
  return <Panel title="Pengaturan penggunaan AI" description="Atur cakupan dan keamanan penggunaan AI untuk setiap client." action={<Cpu className="size-5 text-purple-600" />}>
    <div className="mt-7 flex justify-end"><Button className="cta-primary" onClick={openCreate}><Plus className="size-4" />Buat kebijakan</Button></div>
    {policies.length > 0 && <div className="mt-4 overflow-hidden rounded-xl border border-slate-200"><div className="divide-y divide-slate-100">{policies.map((item) => <div key={item.id} className="flex flex-wrap items-center justify-between gap-3 bg-white px-4 py-3.5"><div><p className="font-semibold">{item.name}</p><p className="mt-0.5 text-xs text-slate-500">{item.client_id ? clients.find((client) => client.id === item.client_id)?.name ?? "Client" : "Semua client dalam organisasi"} · Data disimpan {item.retention_days} hari</p></div><div className="flex items-center gap-2"><Status value={item.is_active ? "active" : "inactive"} /><Button size="sm" variant="outline" onClick={() => openEdit(item)}>Edit</Button><Button size="sm" variant="outline" disabled={busy} onClick={() => onSave({ ...item, is_active: !item.is_active })}>{item.is_active ? "Nonaktifkan" : "Aktifkan"}</Button></div></div>)}</div></div>}
    <Dialog open={dialogOpen} onOpenChange={(open) => { if (!open) closeDialog(); }}><DialogContent className="max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>{draft.id ? "Edit kebijakan AI" : "Buat kebijakan AI"}</DialogTitle><DialogDescription>Atur nama, cakupan client, retensi data, dan aturan keamanan kebijakan ini.</DialogDescription></DialogHeader><div className="grid gap-4 py-2"><label className="text-sm font-semibold text-slate-700">Nama kebijakan<Input className="mt-1.5" aria-label="Nama kebijakan AI" placeholder="Contoh: Kebijakan AI standar" value={draft.name} onChange={(event) => setDraft({ ...draft, name: event.target.value })} /></label><label className="text-sm font-semibold text-slate-700">Berlaku untuk<select aria-label="Berlaku untuk client" className="mt-1.5 h-9 w-full rounded-lg border border-input bg-white px-2 text-sm font-normal" value={draft.client_id ?? ""} onChange={(event) => setDraft({ ...draft, client_id: event.target.value || null })}>{clientOptions(clients)}</select></label><label className="text-sm font-semibold text-slate-700">Simpan data selama<Input className="mt-1.5" aria-label="Lama penyimpanan data AI dalam hari" type="number" min="1" max="3650" value={draft.retention_days} onChange={(event) => setDraft({ ...draft, retention_days: Number(event.target.value) })} /><span className="mt-1 block text-xs font-normal text-slate-500">hari</span></label><div><h3 className="font-bold text-slate-950">Aturan keamanan</h3><div className="mt-3 grid gap-3">{fields.map(([key, label, help]) => <label key={key} className={`flex cursor-pointer items-start gap-3 rounded-xl border p-4 text-sm transition-colors ${draft[key] ? "border-blue-200 bg-blue-50/50" : "border-slate-200 bg-white hover:bg-slate-50"}`}><input className="mt-0.5 size-4 accent-blue-600" type="checkbox" checked={draft[key]} onChange={(event) => setDraft({ ...draft, [key]: event.target.checked })} /><span><span className="block font-semibold text-slate-900">{label}</span><span className="mt-1 block text-xs font-normal leading-5 text-slate-500">{help}</span></span></label>)}</div></div></div><DialogFooter><Button variant="outline" onClick={closeDialog}>Batal</Button><Button className="cta-primary" disabled={busy} onClick={submit}>{busy ? <Loader2 className="size-4 animate-spin" /> : <Plus className="size-4" />}{draft.id ? "Simpan perubahan" : "Buat kebijakan"}</Button></DialogFooter></DialogContent></Dialog>
  </Panel>;
}
function AuditPanel({ audits, busy, canManage, workItems, members, clients, onSample, onFinding, onStatus }: { audits: AuditData; busy: string | null; canManage: boolean; workItems: WorkItem[]; members: Member[]; clients: Client[]; onSample: (payload: Record<string, unknown>) => void; onFinding: (payload: Record<string, unknown>) => void; onStatus: (id: string, status: string, resolution?: string) => void }) {
  const [query, setQuery] = useState(""); const [severity, setSeverity] = useState("all"); const [statusFilter, setStatusFilter] = useState("all"); const [clientFilter, setClientFilter] = useState("all"); const [ownerFilter, setOwnerFilter] = useState("all"); const [dueFilter, setDueFilter] = useState("all"); const [sampleOpen, setSampleOpen] = useState(false); const [findingOpen, setFindingOpen] = useState(false); const [resolutionOpen, setResolutionOpen] = useState(false); const [selectedSample, setSelectedSample] = useState<AuditSample | null>(null); const [selectedFinding, setSelectedFinding] = useState<AuditFinding | null>(null); const [pendingStatus, setPendingStatus] = useState(""); const [resolution, setResolution] = useState(""); const [validationError, setValidationError] = useState("");
  const [sampleDraft, setSampleDraft] = useState({ work_item_id: "", rating: "", notes: "" });
  const [findingDraft, setFindingDraft] = useState({ audit_sample_id: "", finding_type: "", description: "", severity: "minor", due_date: "", evidence: "", root_cause: "", owner_id: "" });
  
  const now = useMemo(() => new Date(), []);
  
  const closeResolutionDialog = () => { setResolutionOpen(false); setPendingStatus(""); setResolution(""); setValidationError(""); };
  const closeSampleDialog = () => { setSampleOpen(false); setSampleDraft({ work_item_id: "", rating: "", notes: "" }); };
  const closeFindingDialog = () => { setFindingOpen(false); setFindingDraft({ audit_sample_id: "", finding_type: "", description: "", severity: "minor", due_date: "", evidence: "", root_cause: "", owner_id: "" }); };
  
  const isOverdue = useCallback((item: AuditFinding) => Boolean(item.due_date && new Date(item.due_date) < now && item.status !== "closed"), [now]);
  const dueState = useCallback((item: AuditFinding) => !item.due_date ? "no_due" : isOverdue(item) ? "overdue" : "on_track", [isOverdue]);
  
  const findings = audits.findings.filter((item) => (severity === "all" || item.severity === severity) && (statusFilter === "all" || item.status === statusFilter) && (clientFilter === "all" || item.client_id === clientFilter) && (ownerFilter === "all" || item.owner_id === ownerFilter) && (dueFilter === "all" || dueState(item) === dueFilter) && `${item.finding_type} ${item.description ?? ""}`.toLowerCase().includes(query.toLowerCase()));
  const overdue = audits.findings.filter(isOverdue).length;
  const findingKeys = audits.findings.map((item) => `${item.finding_type.trim().toLowerCase()}|${(item.description ?? "").trim().toLowerCase()}`);
 const repeated = findingKeys.filter((key, index) => findingKeys.indexOf(key) !== index).filter((key, index, list) => list.indexOf(key) === index).length;
  const trend = ["minor", "moderate", "major", "critical"].map((level) => ({ level, count: audits.findings.filter((item) => item.severity === level).length })); const metric = (label: string, value: number) => <Metric label={label} value={`${value}`} />;
  const exportCsv = () => { const escape = (value: unknown) => `"${String(value ?? "").replaceAll('"', '""')}"`; const csv = ["finding_type,severity,status,description,client,owner,corrective_task"].concat(findings.map((item) => [item.finding_type, item.severity, item.status, item.description, clients.find((client) => client.id === item.client_id)?.name, members.find((member) => member.profile_id === item.owner_id)?.name, item.corrective_task_id].map(escape).join(","))).join("\r\n"); const url = URL.createObjectURL(new Blob([`\ufeff${csv}`], { type: "text/csv;charset=utf-8" })); const link = document.createElement("a"); link.href = url; link.download = "audit-findings.csv"; link.click(); URL.revokeObjectURL(url); };
  return <Panel title="Sampel audit dan temuan" description="Pantau kualitas kontrol, detail pemilik, evidence, akar masalah, dan tindak lanjut." action={canManage ? <div className="flex gap-2"><Button variant="outline" onClick={() => onSample({ action: "auto_sample", sample_size: 10 })}><RefreshCw className="size-4" /> Sampling otomatis</Button><Button onClick={() => setSampleOpen(true)} className="cta-primary"><Plus className="size-4" /> Ambil sampel</Button></div> : <span className="text-xs font-semibold text-amber-700">Read-only</span>}><div className="grid gap-3 sm:grid-cols-3 lg:grid-cols-8">{metric("Sampel", audits.samples.length)}{metric("Temuan", audits.findings.length)}{metric("Berulang", repeated)}{metric("Terbuka", audits.findings.filter((x) => x.status !== "closed").length)}{metric("Overdue", overdue)}{metric("Major", audits.findings.filter((x) => x.severity === "major").length)}{metric("Critical", audits.findings.filter((x) => x.severity === "critical").length)}{metric("Closed", audits.findings.filter((x) => x.status === "closed").length)}</div><div className="mt-4 rounded-xl border border-slate-200 bg-slate-50 p-3"><p className="text-sm font-semibold text-slate-900">Heatmap severity</p><div className="mt-2 grid grid-cols-4 gap-2">{trend.map((item) => <div key={item.level} className="rounded-lg bg-white p-2 text-center"><p className="text-xs capitalize text-slate-500">{item.level}</p><p className="text-lg font-bold text-slate-900">{item.count}</p></div>)}</div></div><div className="mt-5 flex flex-wrap gap-2"><Input className="max-w-sm" placeholder="Cari finding atau uraian" value={query} onChange={(e) => setQuery(e.target.value)} /><select className="h-9 rounded-lg border border-input bg-white px-2 text-sm" value={severity} onChange={(e) => setSeverity(e.target.value)}><option value="all">Semua severity</option><option value="minor">Minor</option><option value="moderate">Moderate</option><option value="major">Major</option><option value="critical">Critical</option></select><select className="h-9 rounded-lg border border-input bg-white px-2 text-sm" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}><option value="all">Semua status</option>{[...new Set(audits.findings.map((item) => item.status))].map((value) => <option key={value} value={value}>{value}</option>)}</select><select className="h-9 rounded-lg border border-input bg-white px-2 text-sm" value={clientFilter} onChange={(e) => setClientFilter(e.target.value)}><option value="all">Semua client</option>{clients.map((client) => <option key={client.id} value={client.id}>{client.name}</option>)}</select><select className="h-9 rounded-lg border border-input bg-white px-2 text-sm" value={ownerFilter} onChange={(e) => setOwnerFilter(e.target.value)}><option value="all">Semua owner</option>{members.map((member) => <option key={member.profile_id} value={member.profile_id}>{member.name}</option>)}</select><select className="h-9 rounded-lg border border-input bg-white px-2 text-sm" value={dueFilter} onChange={(e) => setDueFilter(e.target.value)}><option value="all">Semua due date</option><option value="overdue">Overdue</option><option value="on_track">Belum overdue</option><option value="no_due">Tanpa due date</option></select><Button variant="outline" disabled={!canManage} onClick={() => setFindingOpen(true)}><Plus className="size-4" /> Buat finding</Button><Button variant="outline" onClick={exportCsv}>Export CSV</Button></div><div className="mt-4 grid gap-3 lg:grid-cols-2"><div className="divide-y divide-slate-100">{findings.length ? findings.map((item) => <div key={item.id} onClick={() => setSelectedFinding(item)} className={`rounded-xl border p-3 mb-2 cursor-pointer ${selectedFinding?.id === item.id ? "border-blue-400 bg-blue-50" : "border-slate-200"}`}><div className="flex flex-wrap items-start justify-between gap-2"><div><p className="font-semibold">{item.finding_type}</p><p className="text-xs text-slate-500">{item.severity} · {item.status} · owner {members.find((m) => m.profile_id === item.owner_id)?.name ?? "belum ditentukan"}</p></div><select className="h-8 rounded border px-1 text-xs" value={item.status} disabled={!canManage} onChange={(e) => { const next = e.target.value; if (["closed", "remediated", "accepted"].includes(next)) { setSelectedFinding(item); setPendingStatus(next); setResolution(item.resolution ?? ""); setValidationError(""); setResolutionOpen(true); } else onStatus(item.id, next); }}><option value="open">Open</option><option value="in_progress">In progress</option><option value="remediated">Remediated</option><option value="accepted">Accepted</option><option value="closed">Closed</option><option value="reopened">Reopened</option></select></div><p className="mt-2 text-sm text-slate-700">{item.description ?? "Tidak ada uraian."}</p><p className="mt-2 text-xs text-slate-500">Due: {item.due_date ? new Date(item.due_date).toLocaleDateString("id-ID") : "-"} · Evidence: {item.evidence || "-"} · Akar masalah: {item.root_cause || "-"} · Corrective task: {item.corrective_task_id || "otomatis/belum ada"}</p></div>) : <Empty icon={CheckCircle2} text="Belum ada temuan yang sesuai filter." />}</div><div className="rounded-xl border border-slate-200 p-4"><h3 className="font-bold">Detail temuan</h3>{selectedFinding && <div className="mb-4 rounded-lg bg-blue-50 p-3 text-sm"><p className="font-semibold">{selectedFinding.finding_type}</p><p className="mt-1 text-slate-700">{selectedFinding.description || "Tidak ada uraian."}</p><p className="mt-2 text-xs text-slate-600">Owner: {members.find((member) => member.profile_id === selectedFinding.owner_id)?.name || "belum ditentukan"} · Client: {clients.find((client) => client.id === selectedFinding.client_id)?.name || "-"} · Corrective task: {selectedFinding.corrective_task_id || "belum ada"}</p></div>}<h3 className="font-bold">Detail sampel</h3>{audits.samples.length ? audits.samples.map((sample) => <button key={sample.id} className={`mt-2 block w-full rounded-lg border p-3 text-left text-sm ${selectedSample?.id === sample.id ? "border-blue-400 bg-blue-50" : "border-slate-200"}`} onClick={() => setSelectedSample(sample)}><span className="font-semibold">{workItems.find((w) => w.id === sample.work_item_id)?.title ?? sample.work_item_id}</span><span className="block text-xs text-slate-500">Rating {sample.rating ?? "-"} · {new Date(sample.sampled_at).toLocaleDateString("id-ID")}</span></button>) : <p className="mt-3 text-sm text-slate-500">Belum ada sampel.</p>}{selectedSample && <p className="mt-4 text-sm text-slate-600">{selectedSample.notes || "Tidak ada catatan sampel."}</p>}</div></div><Dialog open={sampleOpen} onOpenChange={(open) => { if (!open) closeSampleDialog(); }}><DialogContent><DialogHeader><DialogTitle>Ambil sampel manual</DialogTitle></DialogHeader><div className="grid gap-3"><select className="h-9 rounded border px-2" value={sampleDraft.work_item_id} onChange={(event) => setSampleDraft({ ...sampleDraft, work_item_id: event.target.value })}><option value="">Pilih work item</option>{workItems.map((w) => <option key={w.id} value={w.id}>{w.title}</option>)}</select><Input placeholder="Rating (opsional)" value={sampleDraft.rating} onChange={(event) => setSampleDraft({ ...sampleDraft, rating: event.target.value })} /><Input placeholder="Catatan" value={sampleDraft.notes} onChange={(event) => setSampleDraft({ ...sampleDraft, notes: event.target.value })} /></div><DialogFooter><Button variant="outline" onClick={closeSampleDialog}>Batal</Button><Button className="cta-primary" onClick={() => { if (!sampleDraft.work_item_id) return; onSample({ action: "sample", work_item_id: sampleDraft.work_item_id, rating: sampleDraft.rating || null, notes: sampleDraft.notes || null }); closeSampleDialog(); }}>Simpan</Button></DialogFooter></DialogContent></Dialog><Dialog open={findingOpen} onOpenChange={(open) => { if (!open) closeFindingDialog(); }}><DialogContent><DialogHeader><DialogTitle>Buat finding</DialogTitle></DialogHeader><div className="grid gap-3"><select className="h-9 rounded border px-2" value={findingDraft.audit_sample_id} onChange={(event) => setFindingDraft({ ...findingDraft, audit_sample_id: event.target.value })}><option value="">Pilih sampel</option>{audits.samples.map((s) => <option key={s.id} value={s.id}>{workItems.find((w) => w.id === s.work_item_id)?.title ?? s.id}</option>)}</select><Input placeholder="Jenis finding" value={findingDraft.finding_type} onChange={(event) => setFindingDraft({ ...findingDraft, finding_type: event.target.value })} /><Input placeholder="Uraian finding" value={findingDraft.description} onChange={(event) => setFindingDraft({ ...findingDraft, description: event.target.value })} /><select className="h-9 rounded border px-2" value={findingDraft.severity} onChange={(event) => setFindingDraft({ ...findingDraft, severity: event.target.value })}><option value="minor">Minor</option><option value="moderate">Moderate</option><option value="major">Major</option><option value="critical">Critical</option></select><Input type="date" value={findingDraft.due_date} onChange={(event) => setFindingDraft({ ...findingDraft, due_date: event.target.value })} /><Input placeholder="Evidence" value={findingDraft.evidence} onChange={(event) => setFindingDraft({ ...findingDraft, evidence: event.target.value })} /><Input placeholder="Root cause" value={findingDraft.root_cause} onChange={(event) => setFindingDraft({ ...findingDraft, root_cause: event.target.value })} /><select className="h-9 rounded border px-2" value={findingDraft.owner_id} onChange={(event) => setFindingDraft({ ...findingDraft, owner_id: event.target.value })}><option value="">Owner</option>{members.map((m) => <option key={m.profile_id} value={m.profile_id}>{m.name}</option>)}</select></div><DialogFooter><Button variant="outline" onClick={closeFindingDialog}>Batal</Button><Button className="cta-primary" onClick={() => { if (!findingDraft.audit_sample_id || !findingDraft.finding_type.trim() || !findingDraft.description.trim() || !findingDraft.owner_id || (["major", "critical"].includes(findingDraft.severity) && !findingDraft.due_date)) return; onFinding({ action: "finding", audit_sample_id: findingDraft.audit_sample_id, finding_type: findingDraft.finding_type, description: findingDraft.description, severity: findingDraft.severity, due_date: findingDraft.due_date || null, evidence: findingDraft.evidence || null, root_cause: findingDraft.root_cause || null, owner_id: findingDraft.owner_id }); closeFindingDialog(); }}>Simpan</Button></DialogFooter></DialogContent></Dialog><Dialog open={resolutionOpen} onOpenChange={(open) => { if (!open) closeResolutionDialog(); }}><DialogContent><DialogHeader><DialogTitle>Resolusi temuan</DialogTitle></DialogHeader><div className="grid gap-3"><p className="text-sm text-slate-600">Status terminal memerlukan alasan resolusi.</p><Input placeholder="Tulis resolusi" value={resolution} onChange={(event) => setResolution(event.target.value)} />{validationError && <p className="text-sm text-red-600">{validationError}</p>}</div><DialogFooter><Button variant="outline" onClick={closeResolutionDialog}>Batal</Button><Button className="cta-primary" onClick={() => { if (!resolution.trim() || !selectedFinding) { setValidationError("Resolusi wajib diisi."); return; } onStatus(selectedFinding.id, pendingStatus, resolution.trim()); closeResolutionDialog(); }}>Simpan status</Button></DialogFooter></DialogContent></Dialog></Panel>;
}
function DeadPanel({ items, total, busy, canManage, onRetry }: { items: DeadLetter[]; total: number; busy: string | null; canManage: boolean; onRetry: (id: string) => void }) { return <Panel title="Perlu perhatian: proses gagal" description="Daftar event yang belum berhasil diproses. Coba ulang hanya jika penyebabnya sudah diperiksa; sistem akan memasukkannya kembali ke antrean kerja." action={canManage ? <RotateCcw className="size-5 text-amber-600" /> : <span className="text-xs font-semibold text-amber-700">Hanya lihat</span>}><div className="mb-4 rounded-xl border border-blue-100 bg-blue-50 px-4 py-3 text-sm text-blue-900"><p className="font-semibold">Ini digunakan untuk apa?</p><p className="mt-1 leading-5">Gunakan halaman ini untuk memulihkan proses otomatis yang gagal, misalnya menerima pesan WhatsApp atau membuat ringkasan percakapan. Klik <strong>Coba ulang</strong> setelah integrasi atau data penyebab masalah sudah diperbaiki.</p></div><div className="mb-3 flex flex-wrap items-center gap-2 text-sm"><span className="font-semibold text-slate-900">{total} proses perlu perhatian</span>{items.length < total && <span className="text-slate-500">· Menampilkan {items.length} yang paling lama gagal</span>}</div><div className="divide-y divide-slate-100">{items.length ? items.map((item) => <div key={item.id} className="flex flex-wrap items-center justify-between gap-3 py-3"><div className="min-w-0"><p className="font-semibold text-slate-900">{formatDeadEvent(item.event_type)}</p><p className="mt-0.5 text-xs text-slate-500">Gagal sejak {new Date(item.created_at).toLocaleString("id-ID")} · {item.retry_count} kali percobaan</p>{(item.last_error || item.error_message) && <p className="mt-1 break-words text-xs text-red-700">Penyebab: {item.last_error || item.error_message}</p>}</div>{canManage && <Button size="sm" variant="outline" onClick={() => onRetry(item.id)} disabled={busy === `retry-${item.id}`}><RotateCcw className="size-4" />{busy === `retry-${item.id}` ? "Memproses..." : "Coba ulang"}</Button>}</div>) : <Empty icon={CheckCircle2} text="Tidak ada proses gagal. Semua antrean berjalan normal." />}</div></Panel>; }
function EscalationOperationsPanel({ items, clients, canManage, busy, onResolve }: { items: EscalationInstance[]; clients: Client[]; canManage: boolean; busy: string | null; onResolve: (id: string) => void }) {
  const [query, setQuery] = useState(""); const [clientFilter, setClientFilter] = useState("all"); const [statusFilter, setStatusFilter] = useState("active"); const [priorityFilter, setPriorityFilter] = useState("all"); const [levelFilter, setLevelFilter] = useState("all");
  
  const escalationNow = useMemo(() => new Date().getTime(), []);
  const isOverdue = useCallback((item: EscalationInstance) => !item.resolved_at && new Date(item.escalated_at).getTime() < escalationNow - (item.threshold_hours ?? 24) * 3600000, [escalationNow]);
  const state = useCallback((item: EscalationInstance) => item.resolved_at ? "resolved" : isOverdue(item) ? "overdue" : "active", [isOverdue]);
  
  const rows = items.filter((item) => {
 const clientId = item.client?.id ?? item.work_items?.client_id ?? ""; return (clientFilter === "all" || clientId === clientFilter) && (statusFilter === "all" || state(item) === statusFilter) && (priorityFilter === "all" || item.priority === priorityFilter) && (levelFilter === "all" || item.current_level === levelFilter) && `${item.work_items?.title ?? ""} ${item.client?.name ?? ""}`.toLowerCase().includes(query.toLowerCase()); }); const deliveryLabel = (item: EscalationInstance) => { const statuses = item.notification_delivery_status.map((delivery) => delivery.outcome ?? delivery.status).filter(Boolean); return statuses.length ? statuses.join(", ") : "belum ada status"; }; return <Panel title="Operasional eskalasi" description="Pantau eskalasi aktif, overdue, dan yang sudah diselesaikan." action={<div className="flex gap-2"><Metric label="Aktif" value={`${items.filter((x) => !x.resolved_at).length}`} /><Metric label="Overdue" value={`${items.filter(isOverdue).length}`} /><Metric label="Resolved" value={`${items.filter((x) => x.resolved_at).length}`} /></div>}><div className="flex flex-wrap gap-2"><Input className="max-w-sm" placeholder="Cari client atau work item" value={query} onChange={(e) => setQuery(e.target.value)} /><select className="h-9 rounded-lg border bg-white px-2 text-sm" value={clientFilter} onChange={(e) => setClientFilter(e.target.value)}><option value="all">Semua client</option>{clients.map((client) => <option key={client.id} value={client.id}>{client.name}</option>)}</select><select className="h-9 rounded-lg border bg-white px-2 text-sm" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}><option value="active">Aktif</option><option value="overdue">Overdue</option><option value="resolved">Resolved</option><option value="all">Semua status</option></select><select className="h-9 rounded-lg border bg-white px-2 text-sm" value={priorityFilter} onChange={(e) => setPriorityFilter(e.target.value)}><option value="all">Semua prioritas</option><option value="low">Rendah</option><option value="medium">Sedang</option><option value="high">Tinggi</option><option value="critical">Kritis</option></select><select className="h-9 rounded-lg border bg-white px-2 text-sm" value={levelFilter} onChange={(e) => setLevelFilter(e.target.value)}><option value="all">Semua level</option>{[...new Set(items.map((item) => item.current_level))].map((level) => <option key={level} value={level}>{level}</option>)}</select></div><div className="mt-4 divide-y divide-slate-100">{rows.length ? rows.map((item) => <div key={item.id} className="flex flex-wrap items-center justify-between gap-3 py-3"><div><p className="font-semibold">{item.work_items?.title ?? item.work_item_id}</p><p className="text-xs text-slate-500">{item.client?.name ?? clients.find((c) => c.id === item.work_items?.client_id)?.name ?? "Client tidak diketahui"} · Level {item.current_level} · Priority {item.priority ?? "-"} · Threshold {item.threshold_hours ?? "-"} jam · {state(item)} · {new Date(item.escalated_at).toLocaleString("id-ID")}</p><p className="mt-1 text-xs text-slate-500">Penerima: {item.recipients.map((recipient) => recipient.profile?.full_name ?? recipient.profile?.name).filter(Boolean).join(", ") || "-"} · Delivery: {deliveryLabel(item)}</p></div>{canManage && !item.resolved_at && <Button size="sm" variant="outline" disabled={busy === `resolve-escalation-${item.id}`} onClick={() => onResolve(item.id)}><CheckCircle2 className="size-4" /> Selesaikan</Button>}</div>) : <Empty icon={CheckCircle2} text="Tidak ada eskalasi pada filter ini." />}</div></Panel>; }
function WhatsAppOperationalPanel({ data, groups, connections }: { data: WaInboxData; groups: Group[]; connections: Connection[] }) { const [query, setQuery] = useState(""); const operational = data.operational; const filtered = data.messages.filter((m) => `${m.groupName} ${m.senderName} ${m.content}`.toLowerCase().includes(query.toLowerCase())); const outcome = operational?.delivery.byOutcome ?? {}; return <div className="mt-5"><Panel title="Ringkasan operasional WhatsApp" description="Signal layer operasional; hanya grup whitelist diproses dan chat pribadi tidak dibaca."><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Metric label="Koneksi sehat" value={`${(operational?.connections ?? connections).filter((x) => ["working", "connected", "healthy"].includes(x.status.toLowerCase())).length}`} /><Metric label="Grup aktif" value={`${(operational?.groups ?? groups).filter((x) => "isActive" in x ? x.isActive : x.is_active).length}`} /><Metric label="Mapping verified" value={`${operational?.participantMappings.verified ?? 0}/${operational?.participantMappings.total ?? 0}`} /><Metric label="Pesan periode ini" value={`${operational?.ingestion.messagesInPeriod ?? data.messages.length}`} /><Metric label="Delivery attempts" value={`${operational?.delivery.attemptsInPeriod ?? 0}`} /><Metric label="Delivery sukses" value={`${outcome.sent ?? outcome.delivered ?? 0}`} /><Metric label="Error delivery" value={`${operational?.delivery.errors.length ?? 0}`} /><Metric label="Dead letters" value={`${operational?.deadLetters.length ?? 0}`} /></div><div className="mt-4 rounded-xl border border-amber-200 bg-amber-50 p-3 text-sm text-amber-900">Whitelist grup secara eksplisit sebelum ingest. Pesan private chat diabaikan pada MVP; verifikasi participant ke user aplikasi agar identity resolution aman.</div><div className="mt-4 grid gap-2 text-xs text-slate-600 sm:grid-cols-2"><p>Mapping unverified: <strong>{operational?.participantMappings.unverified ?? 0}</strong></p><p>Inbound terakhir: <strong>{operational?.lastInboundActivityAt ? new Date(operational.lastInboundActivityAt).toLocaleString("id-ID") : "belum ada"}</strong></p></div>{(operational?.delivery.errors.length || operational?.deadLetters.length) ? <div className="mt-4 grid gap-3 md:grid-cols-2"><div className="rounded-xl border border-red-200 bg-red-50 p-3 text-sm"><p className="font-semibold text-red-900">Error delivery</p>{operational?.delivery.errors.slice(0, 4).map((error) => <p key={`${error.connectionId}-${error.createdAt}`} className="mt-1 text-xs text-red-800">{error.errorCode ?? error.status}: {error.error ?? "detail tidak tersedia"}</p>)}</div><div className="rounded-xl border border-amber-200 bg-amber-50 p-3 text-sm"><p className="font-semibold text-amber-900">Dead letters</p>{operational?.deadLetters.slice(0, 4).map((item) => <p key={item.id} className="mt-1 text-xs text-amber-800">{formatDeadEvent(item.eventType)} · {item.error ?? "detail tidak tersedia"}</p>)}</div></div> : null}<Input className="mt-4 max-w-sm" placeholder="Cari grup, pengirim, atau pesan" value={query} onChange={(e) => setQuery(e.target.value)} /><div className="mt-3 divide-y divide-slate-100">{filtered.slice(0, 8).map((message) => <div key={message.id} className="py-3"><p className="font-semibold">{message.groupName} · {message.senderName}</p><p className="text-sm text-slate-700">{message.content}</p><p className="text-xs text-slate-500">{new Date(message.receivedAt).toLocaleString("id-ID")} · {message.messageType}</p></div>)}{!filtered.length && <Empty icon={MessageCircle} text="Belum ada pesan inbound." />}</div>{data.summaries.length > 0 && <div className="mt-4 grid gap-2 md:grid-cols-2">{data.summaries.slice(0, 4).map((summary) => <div key={summary.groupId} className="rounded-lg bg-slate-50 p-3 text-sm"><p className="font-semibold">{summary.groupName}</p><p className="text-slate-600">{summary.deterministicSummary ?? summary.aiSummary ?? `${summary.messageCount} pesan dari ${summary.participantCount} peserta.`}</p></div>)}</div>}</Panel></div>; }
function formatDeadEvent(eventType: string) { const labels: Record<string, string> = { whatsapp_message_received: "Menerima pesan WhatsApp", whatsapp_conversation_summary_requested: "Membuat ringkasan percakapan WhatsApp", ai_extraction_requested: "Memproses saran AI" }; return labels[eventType] ?? eventType.replaceAll("_", " "); }
function HealthPanel({ items }: { items: JobHealth[] }) { return <Panel title="Kesehatan pekerjaan" description="Status worker dan antrean dipantau secara berkala." action={<Activity className="size-5 text-emerald-600" />}><div className="grid gap-3 lg:grid-cols-3">{items.length ? items.map((item) => <div key={item.name} className="rounded-xl border border-slate-200 p-4"><div className="flex items-center justify-between gap-2"><p className="font-semibold text-slate-900">{item.name}</p><Status value={item.status} /></div><div className="mt-4 grid grid-cols-3 gap-2 text-center"><Metric label="Pending" value={`${item.pending}`} /><Metric label="Proses" value={`${item.processing}`} /><Metric label="Gagal" value={`${item.failed}`} /></div><p className="mt-3 text-xs text-slate-500">Aktivitas terakhir: {item.last_activity_at ? new Date(item.last_activity_at).toLocaleString("id-ID") : "belum ada"}</p></div>) : <Empty icon={Activity} text="Data kesehatan belum tersedia." />}</div></Panel>; }
function Metric({ label, value }: { label: string; value: string }) { return <div className="rounded-lg bg-slate-50 p-3"><p className="text-xs text-slate-500">{label}</p><p className="mt-1 text-lg font-bold text-slate-900">{value}</p></div>; }
function Empty({ icon: Icon, text }: { icon: typeof Activity; text: string }) { return <div className="flex flex-col items-center justify-center rounded-xl border border-dashed border-slate-200 px-5 py-10 text-center"><Icon className="size-8 text-slate-300" /><p className="mt-3 text-sm text-slate-500">{text}</p></div>; }
